pub(crate) fn prepare_solar_fuel(&self, units: u16) -> Result<Self, Error> {
    if units == 0 {
        return Err(Error::InvalidFit);
    }
    let mut data = self.data;
    data.fuel_tenths = data
        .fuel_tenths
        .checked_add(units)
        .filter(|&fuel| fuel <= self.fuel_capacity())
