pub(crate) fn subreader(&mut self, length: usize) -> Result<Self, SaveError> {
    let end = self.offset.checked_add(length).ok_or(SaveError::TooLarge)?;
    let bytes = self
        .bytes
        .get(self.offset..end)
        .ok_or(SaveError::Truncated)?;
    self.offset = end;
    Ok(Self::new(bytes))
